import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=None
log=[]
def get_token():
    global tok
    r=urllib.request.Request(B+"/token",method="POST")
    tok=json.load(urllib.request.urlopen(r))["token"]
def call(path):
    global tok
    for _ in range(200):
        if tok is None: get_token()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            log.append((path,e.code,dict(e.headers).get("Retry-After"),body))
            if e.code==404: return None
            if e.code==401: tok=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w); continue
            time.sleep(0.5)
        except Exception as e:
            log.append((path,str(e))); time.sleep(0.5)
    raise SystemExit("failed "+path)
orders=[];seen=set();dups=0
p=1
while True:
    d=call(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen.add(o["id"]); orders.append(o)
    if not d["next"]: break
    p+=1
print("pages",p,"unique",len(orders),"dups",dups)
cust={}
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
reg={"north":0,"south":0,"east":0,"west":0};n=0;missing=[]
for o in orders:
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not (lo<=t.astimezone(timezone.utc)<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=call("/customers/"+c)
    if cust[c] is None: missing.append(o["id"]); continue
    amt=o["amount_cents"]*(100-cust[c]["discount_pct"])
    reg[cust[c]["region"]]+=(amt+50)//100; n+=1
print(missing, set(l[1] for l in log), log[:3])
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
print(res)
json.dump(res,open("/workspace/result.json","w"),indent=2)
EOF
